export function union(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('intervals must be an array');
  }

  const sorted = intervals.slice();

  for (const interval of sorted) {
    if (interval === null || typeof interval !== 'object' ||
        !Number.isFinite(interval.start) || !Number.isFinite(interval.end)) {
      throw new TypeError('interval start and end must be finite numbers');
    }
    if (interval.end < interval.start) {
      throw new RangeError('interval end must not be less than start');
    }
  }

  sorted.sort((a, b) => a.start - b.start);

  const result = [];
  for (const interval of sorted) {
    if (interval.start === interval.end) continue;

    const previous = result[result.length - 1];
    if (previous && interval.start <= previous.end) {
      if (interval.end > previous.end) previous.end = interval.end;
    } else {
      result.push(interval);
    }
  }

  return result;
}
